import React, { useState } from 'react';
import axios from 'axios';

const ExerciseCard = ({ exercise, currentAccount }) => {
  const [selected, setSelected] = useState(null);
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleSubmit = async () => {
    if (selected === null) return alert("Vui lòng chọn đáp án!");
    if (!currentAccount) return alert("Kết nối ví để tiếp tục!");

    setLoading(true);
    try {
      const res = await axios.post('http://localhost:5000/api/submit-answer', {
        exercise_id: exercise._id,
        learner_address: currentAccount,
        selected_option_index: selected
      });
      setResult(res.data);
    } catch (err) {
      alert("Lỗi: " + (err.response?.data?.error || err.message));
    }
    setLoading(false);
  };

  // Logic hiển thị đúng sai
  const getOptionStyle = (idx) => {
    if (result) {
      if (idx === exercise.correct_option_index) return "bg-emerald-500/20 border-emerald-500 text-emerald-300"; // Đáp án đúng
      if (idx === selected && idx !== exercise.correct_option_index) return "bg-red-500/20 border-red-500 text-red-300"; // Chọn sai
      return "opacity-30 border-transparent";
    }
    return selected === idx 
      ? "bg-indigo-600/30 border-indigo-500 text-white" 
      : "bg-white/5 border-transparent hover:bg-white/10 text-gray-300";
  };

  return (
    <div className="glass-panel p-6 flex flex-col h-full relative group">
      {/* Decorative Glow */}
      <div className="absolute -inset-0.5 bg-gradient-to-r from-pink-500 to-indigo-500 rounded-[20px] blur opacity-0 group-hover:opacity-30 transition duration-500"></div>
      
      <div className="relative z-10 flex flex-col h-full">
        {/* Header */}
        <div className="flex justify-between items-start mb-4">
          <span className="px-3 py-1 rounded-full bg-blue-500/20 text-blue-300 text-xs font-bold uppercase tracking-wider border border-blue-500/20">
            {exercise.topic}
          </span>
          <div className="text-right">
            <p className="text-[10px] text-gray-500 uppercase font-bold">Cược</p>
            <p className="text-red-400 font-mono font-bold text-sm">-{exercise.stake_amount} Token</p>
          </div>
        </div>

        {/* Content */}
        <h3 className="text-lg font-medium text-white mb-6 leading-relaxed flex-grow">
          {exercise.question_content}
        </h3>

        {/* Options */}
        <div className="space-y-3 mb-6">
          {exercise.options.map((opt, idx) => (
            <button
              key={idx}
              disabled={!!result || loading}
              onClick={() => setSelected(idx)}
              className={`w-full text-left px-4 py-3 rounded-xl border transition-all duration-200 text-sm ${getOptionStyle(idx)}`}
            >
              <span className="font-bold mr-2 opacity-50">{['A','B','C','D'][idx]}.</span> {opt}
            </button>
          ))}
        </div>

        {/* Footer */}
        {result ? (
          <div className={`p-4 rounded-xl text-center border animate-fade-in ${
            result.is_correct ? 'bg-emerald-500/10 border-emerald-500/30' : 'bg-red-500/10 border-red-500/30'
          }`}>
            <p className={`font-bold ${result.is_correct ? 'text-emerald-400' : 'text-red-400'}`}>
              {result.message}
            </p>
            {result.tx_hash && (
              <a 
                href={`https://sepolia.etherscan.io/tx/${result.tx_hash}`} 
                target="_blank" 
                rel="noreferrer"
                className="text-xs text-blue-400 underline mt-2 block hover:text-blue-300"
              >
                Xem Tx trên Sepolia ↗
              </a>
            )}
          </div>
        ) : (
          <button 
            onClick={handleSubmit}
            disabled={loading || selected === null}
            className={`w-full py-3 rounded-xl font-bold transition-all ${
              loading 
                ? 'bg-gray-700 text-gray-400 cursor-wait'
                : selected !== null 
                  ? 'btn-primary' 
                  : 'bg-gray-800 text-gray-500 cursor-not-allowed'
            }`}
          >
            {loading ? 'Đang xác thực...' : 'Chốt Đáp Án'}
          </button>
        )}
      </div>
    </div>
  );
};

export default ExerciseCard;
